css:
.crebsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a37;
    background: linear-gradient(180deg, #f4f7fa 0%, #eef3f7 100%);
    border-radius: 18px;
}

.crebsim-container * {
    box-sizing: border-box;
}

.crebsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f3d4f 0%, #155e6b 60%, #1a7a7f 100%);
    color: #f3fbfc;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0c3340;
    box-shadow: 0 12px 30px rgba(15, 61, 79, 0.28);
}

.crebsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.crebsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffd9d4;
    background: rgba(214, 69, 65, 0.20);
    border: 1px solid rgba(255, 217, 212, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.crebsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6edef;
}

.crebsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #51606e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.crebsim-period-counter #currentDay,
.crebsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #155e6b;
}

.crebsim-round-name {
    background: rgba(21, 94, 107, 0.12);
    color: #0f3d4f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.crebsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b23b36;
    background: rgba(214, 69, 65, 0.10);
    border: 1px solid rgba(214, 69, 65, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.crebsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.crebsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde6ed;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
    border-top: 4px solid #155e6b;
}

.crebsim-card-cred { border-top-color: #d64541; }
.crebsim-card-perf { border-top-color: #1a7a7f; }
.crebsim-card-ret { border-top-color: #2f8f5b; }
.crebsim-card-risk { border-top-color: #e08a2b; }

.crebsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7a89;
}

.crebsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a37;
    font-variant-numeric: tabular-nums;
}

.crebsim-card-cred .crebsim-value { color: #d64541; }
.crebsim-card-perf .crebsim-value { color: #1a7a7f; }
.crebsim-card-ret .crebsim-value { color: #2f8f5b; }
.crebsim-card-risk .crebsim-value { color: #e08a2b; }

.crebsim-sublabel {
    font-size: 0.75rem;
    color: #7a8896;
    line-height: 1.35;
}

.crebsim-risk-high { border-top-color: #c0322d; }
.crebsim-risk-high .crebsim-value { color: #c0322d; }
.crebsim-risk-low { border-top-color: #2f8f5b; }
.crebsim-risk-low .crebsim-value { color: #2f8f5b; }

.crebsim-cred-high .crebsim-value { color: #2f8f5b; }
.crebsim-cred-low .crebsim-value { color: #c0322d; }

.crebsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde6ed;
    color: #2b3744;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(31, 42, 55, 0.05);
}

.crebsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #155e6b;
}

.crebsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #d64541;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
}

.crebsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.crebsim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #0f3d4f;
    margin-bottom: 6px;
}

.crebsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #3a4753;
}

.crebsim-briefing-text strong { color: #155e6b; }
.crebsim-briefing-text em { color: #b23b36; font-style: italic; }

.crebsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde6ed;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
}

.crebsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0f3d4f;
    border-bottom: 2px solid #e6edf2;
    padding-bottom: 8px;
}

.crebsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3744;
    margin: 14px 0 6px;
}

.crebsim-container select,
.crebsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c5d2dc;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1f2a37;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.crebsim-container select:focus,
.crebsim-container input[type="number"]:focus {
    outline: none;
    border-color: #155e6b;
    box-shadow: 0 0 0 3px rgba(21, 94, 107, 0.16);
}

.crebsim-container select option {
    background-color: #ffffff;
    color: #1f2a37;
}

.crebsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #155e6b;
}

.crebsim-range-readout,
.crebsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #51606e;
    margin-top: 4px;
}

.crebsim-range-readout span:last-child,
.crebsim-alloc-readout span:nth-child(2) {
    color: #155e6b;
    font-weight: 800;
}

.crebsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.crebsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f9fb;
    border: 1px solid #dde6ed;
    border-radius: 9px;
    padding: 8px 12px;
}

.crebsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a4753;
}

.crebsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.crebsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.crebsim-container .btn-primary {
    background: linear-gradient(135deg, #0f3d4f 0%, #1a7a7f 100%);
    border: none;
    color: #f3fbfc;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 61, 79, 0.28);
}

.crebsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.crebsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c5d2dc;
    color: #51606e;
    background: transparent;
}

.crebsim-coach {
    background: linear-gradient(135deg, #fbf3f2 0%, #f6eceb 100%);
    color: #3a2a2a;
    border: 1px solid #ecd4d1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(178, 59, 54, 0.08);
}

.crebsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b23b36;
    margin-bottom: 8px;
}

.crebsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #4a3b3b;
}

.crebsim-coach-body strong { color: #b23b36; }
.crebsim-coach-body em { color: #155e6b; font-style: italic; }

.crebsim-history,
.crebsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde6ed;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
}

.crebsim-history h3,
.crebsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f3d4f;
}

.crebsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4753;
}

.crebsim-container table#usfHistoryTable th {
    background: #f0f5f8;
    color: #0f3d4f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dde6ed;
}

.crebsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6edf2;
    color: #3a4753;
}

.crebsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafc;
}

.crebsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .crebsim-container {
        padding: 14px;
    }
    .crebsim-header h1 {
        font-size: 1.7rem;
    }
    .crebsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .crebsim-value {
        font-size: 2rem;
    }
    .crebsim-clock {
        margin-left: 0;
    }
    .crebsim-period-counter {
        font-size: 0.88rem;
    }
    .crebsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .crebsim-alloc-row {
        flex-wrap: wrap;
    }
    .crebsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .crebsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .pci-cm-*, cardiac crimson/slate) ── */
.pci-cm { margin-top: 8px; }
.pci-cm-incomplete { text-align: center; color: #5b5560; font-size: 1rem; padding: 18px; }
.pci-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.pci-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #7a1728 0%, #b02a3c 55%, #45506b 140%); color: #fff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(122,23,40,0.28); }
.pci-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.pci-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.pci-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0c9ce; }
.pci-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fff; border: 1px solid #e6dade; border-left: 5px solid #b02a3c; border-radius: 14px; padding: 16px 20px; }
.pci-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b626a; }
.pci-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #7a1728; line-height: 1.15; }
.pci-cm-section { margin-bottom: 16px; }
.pci-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b626a; margin-bottom: 8px; }
.pci-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.pci-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.pci-cm-ok { background: #e9f3ec; color: #1f6d3a; border-color: #b3ddbf; }
.pci-cm-no { background: #fbeceb; color: #a5322b; border-color: #eec2be; }
.pci-cm-ico { font-weight: 800; }
.pci-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.pci-cm-kpi { background: #f7f3f4; border: 1px solid #e7dcdf; border-radius: 12px; padding: 12px 14px; text-align: center; }
.pci-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #7a1728; }
.pci-cm-kpi-lbl { margin-top: 2px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: #6b626a; }
.pci-cm-kpi-sub { margin-top: 2px; font-size: 0.68rem; color: #948a90; }
.pci-cm-insights { margin: 0; padding-left: 18px; }
.pci-cm-insights li { font-size: 0.9rem; color: #3f383d; margin-bottom: 6px; line-height: 1.45; }

