(function() {
    'use strict';

    class CredibleBossAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Credible Boss`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Pennine Cardiac Institute).
            this.TRANSITION_BUDGET = 350;     // £350k transition budget (in £k)
            this.UNIT_CONSULTANTS = 11;       // unit consultants
            this.FLIGHT_RISK = 4;             // flight-risk consultants
            this.START_RETAINED = 7;          // 11 - 4 flight-risk treated as "not yet secured"
            this.REPLACE_COST = 180;          // £180k each to replace
            this.QUARTILE_THRESHOLD = 70;     // performance index to stay > top quartile

            // Concept truths (Goodall's expert-leadership default in an expert unit).
            this.TRUE_SOURCE = `clinical`;
            this.TRUE_LEAN = `expert`;
            this.TRUE_APPOINT = `expert_deputy`;
            this.TRUE_BACKING = `sponsor`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cred: 30,                 // leader credibility with consultants & commissioners
                    perf: 62,                 // registry-outcome index (top quartile >= 70)
                    retained: 7,              // unit consultants retained (of 11)
                    risk: 55,                 // re-tender / talent-flight / registry-failure risk (lower better)
                    budgetUsed: 0,            // £k of the £350k transition budget committed
                    retentionSpend: 0,        // £k put into the retention package
                    overIntervened: false,    // board over-rescued in the crisis
                    overPromised: false,      // guaranteed top-decile / zero losses
                    credHistory: [30],
                    perfHistory: [62],
                    retainedHistory: [7],
                    riskHistory: [55],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean to the CLASSIC ERRORS so a blind click-through cannot win:
                // generic "good leader" view, undecided lean, generalist-solo hire, vague rights,
                // retention underfunded, board rescues the crisis, defends the figurehead.
                state.decisions = {
                    source: `generic`,
                    lean: `undecided`,
                    rigour: 50,
                    appoint: `generalist_solo`,
                    rights: `blurred`,
                    sessions: 90,
                    deputy: 90,
                    coaching: 80,
                    retention: 90,
                    backing: `rescue`,
                    caseDecision: `hide`,
                    objection: `appease`,
                    sponsor: 50,
                    defence: `figurehead`,
                    horizon: `window`,
                    kpi: `ranking`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sr = document.getElementById(`sourceInput`);
                const ln = document.getElementById(`leanInput`);
                const rg = document.getElementById(`rigourInput`);
                if (sr) decisions.source = sr.value;
                if (ln) decisions.lean = ln.value;
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const ap = document.getElementById(`appointInput`);
                const ri = document.getElementById(`rightsInput`);
                const se = document.getElementById(`sessionsInput`);
                const de = document.getElementById(`deputyInput`);
                const co = document.getElementById(`coachingInput`);
                const re = document.getElementById(`retentionInput`);
                if (ap) decisions.appoint = ap.value;
                if (ri) decisions.rights = ri.value;
                if (se) decisions.sessions = parseFloat(se.value);
                if (de) decisions.deputy = parseFloat(de.value);
                if (co) decisions.coaching = parseFloat(co.value);
                if (re) decisions.retention = parseFloat(re.value);
                const parts = [decisions.sessions, decisions.deputy, decisions.coaching, decisions.retention];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.sessions + decisions.deputy + decisions.coaching + decisions.retention);
                if (Math.abs(total - this.TRANSITION_BUDGET) > 0.5) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const bk = document.getElementById(`backingInput`);
                const ca = document.getElementById(`caseInput`);
                const ob = document.getElementById(`objectionInput`);
                const sp = document.getElementById(`sponsorInput`);
                if (bk) decisions.backing = bk.value;
                if (ca) decisions.caseDecision = ca.value;
                if (ob) decisions.objection = ob.value;
                if (sp) decisions.sponsor = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.sponsor) || decisions.sponsor < 0 || decisions.sponsor > 100) {
                    warn(`warn_sponsor_range`); return false;
                }
            } else if (round === 4) {
                const df = document.getElementById(`defenceInput`);
                const ho = document.getElementById(`horizonInput`);
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`convictionInput`);
                if (df) decisions.defence = df.value;
                if (ho) decisions.horizon = ho.value;
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 — verbatim v1.0.0 composite, extracted so calculateResults and getPerformanceSummary agree.
            const cred = Math.round(ds.cred);
            const perf = Math.round(ds.perf);
            const retained = Math.round(ds.retained);
            const risk = Math.round(ds.risk);
            const retScore = (retained / this.UNIT_CONSULTANTS) * 100;
            return Math.round(
                cred * 0.34 + perf * 0.26 + retScore * 0.20 + (100 - risk) * 0.20
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let credDelta = 0, perfDelta = 0, retDelta = 0, riskDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where credibility actually comes from (peer trust + trials + registry).
                switch (d.source) {
                    case `clinical`: credDelta += 8; perfDelta += 3; riskDelta -= 8; coachKey = `coach_r1_clinical`; break;
                    case `admin`: credDelta -= 2; riskDelta += 4; coachKey = `coach_r1_admin`; break;
                    case `generic`: credDelta -= 5; riskDelta += 8; coachKey = `coach_r1_generic`; break;
                }

                // Provisional lean — Goodall's default tilts to the expert in an expert unit.
                switch (d.lean) {
                    case `expert`: credDelta += 6; riskDelta -= 5; if (d.source === `clinical`) coachKey = `coach_r1_sharp`; break;
                    case `generalist`: credDelta -= 4; riskDelta += 5; coachKey = `coach_r1_generalistlean`; break;
                    case `undecided`: riskDelta += 2; break;
                }

                // Diagnostic rigour: an evidenced credibility-requirements map de-risks the hire.
                if (d.rigour >= 60) { credDelta += 5; perfDelta += 2; riskDelta -= 5; }
                else if (d.rigour <= 25) { credDelta -= 4; riskDelta += 5; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.source === `clinical` && d.lean === `expert`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Select & structure (Common Errors 1, 2, 3) and allocate the £350k (Error 4).
                const sessions = d.sessions, deputy = d.deputy, coaching = d.coaching, retention = d.retention;
                spend = sessions + deputy + coaching + retention;
                ds.retentionSpend = retention;

                switch (d.appoint) {
                    case `expert_deputy`:
                        // Complementary structure: credibility from the expert, bandwidth from the deputy.
                        credDelta += 12; perfDelta += 5; riskDelta -= 8; coachKey = `coach_r2_expertdeputy`;
                        break;
                    case `expert_solo`:
                        // Error 2: expertise carries credibility but the operation has no manager.
                        credDelta += 9; perfDelta -= 6; riskDelta += 6; coachKey = `coach_r2_expertsolo`;
                        break;
                    case `generalist_solo`:
                        // Error 1: the polished manager has no credibility to command expert workers.
                        credDelta -= 12; perfDelta -= 4; riskDelta += 10; coachKey = `coach_r2_generalistsolo`;
                        break;
                    case `generalist_deputy`:
                        // Manager-led with a clinical adviser: better than solo, but credibility still thin
                        // because final clinical/registry authority sits with a non-clinician.
                        credDelta -= 4; perfDelta -= 1; riskDelta += 3; coachKey = `coach_r2_generalistdeputy`;
                        break;
                }

                // Decision rights — clinician must hold clinical & registry authority to be credible.
                switch (d.rights) {
                    case `clinician`: credDelta += 6; perfDelta += 3; riskDelta -= 5; break;
                    case `manager`: credDelta -= 6; riskDelta += 6; coachKey = `coach_r2_rightsmanager`; break;
                    case `blurred`: credDelta -= 3; perfDelta -= 3; riskDelta += 5; coachKey = `coach_r2_rightsblurred`; break;
                }

                // Protected clinical sessions keep the leader credible at the bedside.
                if (sessions >= 70) { credDelta += 4; }
                else if (sessions <= 20) { credDelta -= 3; }

                // Deputy/COO management bandwidth — fixes the rota/budget/commissioner load.
                if (deputy >= 70) { perfDelta += 5; riskDelta -= 4; }
                else if (deputy <= 20) { perfDelta -= 5; riskDelta += 4; if (d.appoint === `expert_solo`) coachKey = `coach_r2_nodeputy`; }

                // Leadership coaching builds managerial skill in whoever was appointed.
                if (coaching >= 60) { perfDelta += 3; }

                // Consultant retention (Error 4): each flight-risk consultant secured protects the data.
                // ~£70k+ holds roughly one consultant's worth; underfunding loses authors of the registry.
                let secured = Math.min(this.FLIGHT_RISK, Math.floor(retention / 75));
                let lost = this.FLIGHT_RISK - secured;
                retDelta += secured;
                credDelta += secured * 2;
                perfDelta += secured * 2 - lost * 3;
                riskDelta += lost * 6 - secured * 3;
                if (retention <= 20) { coachKey = `coach_r2_noretention`; }

                summaryKey = (d.appoint === `expert_deputy` && d.rights === `clinician` && retention >= 150) ? `sum_r2_good` :
                             (d.appoint === `generalist_solo` ? `sum_r2_generalist` :
                             (retention <= 40 ? `sum_r2_noretention` : `sum_r2_weak`));
            } else if (round === 3) {
                // Week-8 crisis: sponsorship vs interference (Common Error 5).
                switch (d.backing) {
                    case `sponsor`: credDelta += 12; perfDelta += 4; riskDelta -= 10; coachKey = `coach_r3_sponsor`; break;
                    case `rescue`: credDelta -= 14; perfDelta += 1; riskDelta += 8; ds.overIntervened = true; coachKey = `coach_r3_rescue`; break;
                    case `distance`: credDelta -= 8; perfDelta -= 5; riskDelta += 9; coachKey = `coach_r3_distance`; break;
                }

                // The poor-outcome case & the registry submission.
                switch (d.caseDecision) {
                    case `clinical_review`: credDelta += 6; perfDelta += 6; riskDelta -= 8; break;
                    case `hide`: perfDelta -= 4; riskDelta += 10; coachKey = `coach_r3_hide`; break;
                    case `board_audit`: credDelta -= 7; riskDelta += 4; if (d.backing !== `sponsor`) coachKey = `coach_r3_audit`; break;
                }

                // The two objecting consultants.
                switch (d.objection) {
                    case `engage`: credDelta += 6; retDelta += 0; riskDelta -= 5; break;
                    case `appease`: credDelta -= 8; riskDelta += 6; coachKey = `coach_r3_appease`; break;
                    case `ignore`: credDelta -= 3; retDelta -= 1; riskDelta += 5; break;
                }
                // Clamp retention to a sane range (can't lose more than were retained, cap at 11).
                if (retDelta < 0) ds.retained = Math.max(0, ds.retained + retDelta), retDelta = 0;

                // How firmly the board holds the line on the leader's authority.
                if (d.sponsor >= 60 && d.backing === `sponsor`) { credDelta += 5; riskDelta -= 4; }
                else if (d.sponsor <= 25) { credDelta -= 4; riskDelta += 4; }

                summaryKey = (d.backing === `sponsor` && d.caseDecision === `clinical_review` && d.objection === `engage`) ? `sum_r3_good` :
                             (d.backing === `rescue` ? `sum_r3_rescue` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the outcome to stakeholders (18-month durability, not just surviving the window).
                switch (d.defence) {
                    case `model`: credDelta += 12; perfDelta += 3; riskDelta -= 10; coachKey = `coach_r4_model`; break;
                    case `figurehead`: credDelta -= 4; riskDelta += 8; coachKey = `coach_r4_figurehead`; break;
                    case `spin`: credDelta -= 8; riskDelta += 10; coachKey = `coach_r4_spin`; break;
                }

                switch (d.horizon) {
                    case `eighteen`: credDelta += 8; perfDelta += 2; riskDelta -= 8; if (d.defence === `model`) coachKey = `coach_r4_durable`; break;
                    case `window`: riskDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_window` : coachKey; break;
                    case `overpromise`: credDelta -= 6; riskDelta += 12; ds.overPromised = true; coachKey = `coach_r4_overpromise`; break;
                }

                switch (d.kpi) {
                    case `credibility`: credDelta += 6; perfDelta += 2; riskDelta -= 4; break;
                    case `ranking`: riskDelta += 2; break;
                    case `cost`: credDelta -= 4; riskDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_cost` : coachKey; break;
                }

                if (d.conviction >= 60) { credDelta += 5; riskDelta -= 4; }
                else if (d.conviction <= 25) { credDelta -= 5; riskDelta += 5; }

                summaryKey = (d.defence === `model` && d.horizon === `eighteen` && d.kpi === `credibility`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the £350k transition budget is committed in Round 2.
            ds.budgetUsed = Math.min(this.TRANSITION_BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas. Credibility is the headline driver; performance follows; risk 0–100 lower better.
            ds.cred = Math.max(0, Math.min(100, Math.round(ds.cred + credDelta)));
            ds.perf = Math.max(0, Math.min(100, Math.round(ds.perf + perfDelta)));
            ds.retained = Math.max(0, Math.min(this.UNIT_CONSULTANTS, ds.retained + retDelta));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            ds.credHistory.push(ds.cred);
            ds.perfHistory.push(ds.perf);
            ds.retainedHistory.push(ds.retained);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                cred: ds.cred,
                credDelta: Math.round(credDelta),
                perf: ds.perf,
                perfDelta: Math.round(perfDelta),
                retained: ds.retained,
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                budgetUsed: ds.budgetUsed,
                overIntervened: ds.overIntervened,
                overPromised: ds.overPromised,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(vK) {
            // Locale-aware GBP, value is in £k. English "£350,000" / "£90,000"; Spanish "350.000 £".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const pounds = Math.round(vK * 1000);
            if (lang === `es`) {
                return `${pounds.toLocaleString(`es-ES`)} £`;
            }
            return `£${pounds.toLocaleString(`en-GB`)}`;
        }

