        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const cred = Math.round(ds.cred);
            const perf = Math.round(ds.perf);
            const retained = Math.round(ds.retained);
            const risk = Math.round(ds.risk);

            // v1.1.0 — reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const credible = cred >= 60;
            const topQuartile = perf >= this.QUARTILE_THRESHOLD;
            const teamHeld = retained >= 9;
            const lowRisk = risk <= 35;
            const collapsed = cred <= 25 || retained <= 6 || risk >= 70;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_faltering`;
            if (credible && topQuartile && teamHeld && lowRisk && composite >= 75) tierKey = `grade_durable`;
            else if (credible && topQuartile && teamHeld) tierKey = `grade_window`;
            else if (collapsed) tierKey = `grade_collapse`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (credible && topQuartile && teamHeld) insights.push(window.mySimulation.t(`insight_credible`));
            else if (collapsed) insights.push(window.mySimulation.t(`insight_collapse`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!topQuartile) insights.push(window.mySimulation.t(`insight_quartile`));
            if (retained <= 7) insights.push(window.mySimulation.t(`insight_retention`));
            else if (retained >= 10) insights.push(window.mySimulation.t(`insight_team`));
            if (ds.overIntervened) insights.push(window.mySimulation.t(`insight_overintervene`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (cred >= 70 && risk <= 30) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                cred: cred,
                perf: perf,
                retained: retained,
                risk: risk,
                credible: credible,
                topQuartile: topQuartile,
                teamHeld: teamHeld,
                lowRisk: lowRisk,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="pci-cm"><p class="pci-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="pci-cm-chip ` + (ok ? `pci-cm-ok` : `pci-cm-no`) + `">` +
                `<span class="pci-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="pci-cm-kpi"><div class="pci-cm-kpi-val">` + val +
                `</div><div class="pci-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="pci-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="pci-cm">` +
  `<div class="pci-cm-head">` +
    `<div class="pci-cm-score"><div class="pci-cm-score-num">` + Math.round(s.composite) +
       `<span class="pci-cm-score-den">/100</span></div>` +
       `<div class="pci-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="pci-cm-verdict"><div class="pci-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="pci-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="pci-cm-section"><div class="pci-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="pci-cm-chips">` + chip(!!s.credible, t(`cm_t_credible`)) + chip(!!s.topQuartile, t(`cm_t_quartile`)) +
