  `<div class="pci-cm-section"><div class="pci-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="pci-cm-kpis">` +
      kpi(t(`cm_lbl_cred`), Math.round(s.cred), t(`cm_sub_cred`)) +
      kpi(t(`cm_lbl_perf`), Math.round(s.perf), t(`cm_sub_perf`)) +
      kpi(t(`cm_lbl_ret`), Math.round(s.retained) + ` / ` + this.UNIT_CONSULTANTS, t(`cm_sub_ret`)) +
      kpi(t(`cm_lbl_risk`), Math.round(s.risk), t(`cm_sub_risk`)) +
    `</div></div>` +
  (insights ? `<div class="pci-cm-section"><div class="pci-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="pci-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
