        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overIntervened) return window.mySimulation.t(`hint_overintervene`);
            if (ds.overPromised) return window.mySimulation.t(`hint_overpromise`);
            if (ds.retained <= 6 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_retention`);
            if (ds.cred <= 25) return window.mySimulation.t(`hint_cred`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (state.currentPeriod >= 3 && ds.perf < this.QUARTILE_THRESHOLD) return window.mySimulation.t(`hint_quartile`);
            if (ds.cred >= 65 && ds.perf >= this.QUARTILE_THRESHOLD && ds.risk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

